"""Create a concise C1 evidence page from measurements, without promoting failed runs."""
import json,html
from pathlib import Path
R=Path('Saved/LowerBodyContact/C1')
def read(name):return json.loads((R/name).read_text(encoding='utf-8-sig'))
def table(headers,rows):return '<table><thead><tr>'+''.join('<th>'+html.escape(str(x))+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
def main():
 a=read('contract-audit.json');r=read('runtime-audit.json');trace=read('formula-trace.json');wide=read('wide-angle-existing-fit.json')
 paired=[p for p in r['poses'] if p.get('core_on_captured')];accepted=[p for p in paired if p.get('accepted_same_lowerbody_pose') and p.get('accepted_stable_surface')]
 report=['<h1>C1 · 原版 VaM 运行时姿态审计</h1>','<p>默认创造场景 · Preset_QiMeng-b · 无额外形变插件。以实际骨骼矩阵为准，不以相同 UI 角度认定姿态相同。</p>',f'<p class="hero">预设匹配 {sum(x["matched"] for x in r["appearance_identity"])} / {len(r["appearance_identity"])} · 已配对 {len(paired)} · 通过下半身稳定性与姿态检查 {len(accepted)}</p>', '<h2>证据范围</h2><p>身体物理关闭；面部眨眼仍有记录，不参与下半身稳定性验收。记录到的原版 SetDAZMorph 驱动分关闭／开启两组。保留体型 MCM。诊断采用同步调度，未用于游戏性能评估。未增加第三方形变插件对照，符合本次要求。</p>', '<p>原版流程先启动诊断采样器，清除场景／会话插件后再加载人物预设。被否决的默认人物、异步错帧及过期体型缓冲读取均保留在单独目录，不计入当前结论。</p>', '<h2>实际资产</h2><p>contract: <code>'+a['contract_id']+'</code></p><p>当前确实是小角度 TriAx→LBS 拟合：训练 ±15°/±30°，原验证 ±22°；原状态为 pending_runtime_calibration。现有矩阵和逆矩阵最大乘积误差 '+str(a['bind_inverse_max_abs'])+'。</p>']
 report+=['<h2>参考骨骼差异：真实运行时 vs 导入 contract</h2>',table(['骨骼','中心差 cm','参考朝向差 °'],[(b['bone'],f'{b["center_error_cm"]:.5f}',f'{b["orientation_error_deg"]:.5f}') for b in r['bind_comparison'] if b['bone'] in ['hip','pelvis','lThigh','rThigh','lShin','rShin']]),'<p>运行时 morphOrientationOffsets 中可追踪到 a07 的实际贡献。只将非零贡献且与 contract 存在差异的项目列为已证实；其余公式仍是候选。</p>']
 report+=['<h2>姿态配对与实际表面</h2>',table(['姿态','矩阵差','下半身重复最大差 cm','核心修形表面最大变化 cm','有效配对'],[(p['pose'],f'{p.get("lowerbody_matrix_max_abs",float("nan")):.7g}',f'{max(p.get("off_repeat_lowerbody",{}).get("maximum_cm",float("nan")),p.get("on_repeat_lowerbody",{}).get("maximum_cm",float("nan"))):.6g}',f'{p.get("core_surface_difference",{}).get("maximum_cm",float("nan")):.5f}',p.get('accepted_same_lowerbody_pose',False) and p.get('accepted_stable_surface',False)) for p in r['poses']])]
 report+=['<h2>隔离原 LBS 拟合误差</h2><p>输入使用实际 VaM 的 pre-skin 体型与 bind/current 矩阵，只替换为当前 contract 的源 LBS 权重。此项不是最终 UE 辅助骨资产回放；下半身范围为源空间高度 25–115 cm，最大值保留顶点编号。</p>',table(['姿态','下半身 RMS cm','P95 cm','最大 cm','源顶点'],[(p['pose'],*[f'{p.get("lower_body_source_lbs_vs_vam_raw",{}).get(k,float("nan")):.4f}' for k in ['rms_cm','p95_cm','maximum_cm']],p.get('lower_body_source_lbs_vs_vam_raw',{}).get('maximum_vertex','')) for p in r['poses']])]
 report+=['<h2>体型输入核查</h2><pre>'+html.escape(json.dumps(r['source_shape_difference'],ensure_ascii=False,indent=2))+'</pre><p>若此项未通过或仍有隐藏 morph 差异，不将表面差异全归因于蒙皮。</p>', '<h2>完整数据</h2><ul>'+''.join('<li><a href="'+f+'">'+t+'</a></li>' for f,t in [('runtime-audit.json','实际表面、身份、矩阵、隐藏 morph 对照'),('formula-trace.json','全部保留／未执行公式追踪'),('wide-angle-existing-fit.json','360 个大角度数学探针（非真实 VaM 目标）'),('contract-audit.json','实际 contract 与轴／旋转顺序审计'),('runtime/progress.log','本次实际采样过程')])+'</ul>']
 doc='<!doctype html><meta charset="utf-8"><title>C1 原版 VaM 审计</title><style>body{max-width:1100px;margin:40px auto;padding:0 24px;background:#15191d;color:#e7ecee;font:16px/1.6 system-ui}h1,h2{color:#fff}h2{margin-top:42px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:8px;border-bottom:1px solid #38434a;text-align:left}th{color:#91d6c7}.hero{padding:18px;background:#253d3a}a{color:#82c8ee}code,pre{white-space:pre-wrap;overflow-wrap:anywhere}</style>'+''.join(report)
 (R/'compare.html').write_text(doc,encoding='utf-8');print(R/'compare.html')
if __name__=='__main__':main()
